const brands = [
  { bid: 'WV', bname: 'Wellness Vibe' },
  { bid: 'RV', bname: 'Rivesh Vade' },
  { bid: 'BF', bname: 'Bodhmarga Foundation' },
];
const platforms = ['Instagram', 'Facebook', 'YouTube', 'LinkedIn'];
const suffix = { Instagram: 'IG', Facebook: 'FB', YouTube: 'YT', LinkedIn: 'LI' };

function accountType(bid, platform) {
  if (platform === 'Instagram') return 'Business/Creator';
  if (platform === 'Facebook') return 'Page';
  if (platform === 'YouTube') return 'Channel';
  if (platform === 'LinkedIn') return (bid === 'RV') ? 'Personal' : 'Page';
  return '';
}
function credName(bid, platform) {
  if (platform === 'Instagram' || platform === 'Facebook') return 'META_' + bid;
  if (platform === 'YouTube') return 'GOOGLE_' + bid;
  if (platform === 'LinkedIn') return 'LINKEDIN_' + bid;
  return '';
}
function idHint(platform, atype) {
  if (platform === 'Instagram') return 'FILL_IG_BUSINESS_ID';
  if (platform === 'Facebook') return 'FILL_FB_PAGE_ID';
  if (platform === 'YouTube') return 'FILL_YT_CHANNEL_ID';
  if (platform === 'LinkedIn') return (atype === 'Personal') ? 'FILL_LI_MEMBER_ID' : 'FILL_LI_ORG_URN_ID';
  return '';
}
function notes(platform, atype) {
  if (platform === 'LinkedIn' && atype === 'Personal') {
    return 'LinkedIn Personal/Creator: no supported public API for profile analytics; collector returns PARTIAL with NULL metrics by design.';
  }
  return '';
}

const rows = [];
for (let b = 0; b < brands.length; b++) {
  const br = brands[b];
  for (let p = 0; p < platforms.length; p++) {
    const platform = platforms[p];
    const atype = accountType(br.bid, platform);
    rows.push({
      Account_ID: br.bid + '_' + suffix[platform],
      Brand_ID: br.bid,
      Brand_Name: br.bname,
      Platform: platform,
      Account_Type: atype,
      Platform_Account_ID: idHint(platform, atype),
      Account_Name: br.bname + ' ' + platform,
      Active: 'TRUE',
      Timezone: 'Asia/Kolkata',
      Credential_Name: credName(br.bid, platform),
      Last_Sync: '',
      Notes: notes(platform, atype),
    });
  }
}
return rows.map(function (r) { return { json: r }; });
